"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Extract selected clips from FSD50K's split zip archives (FSD50K.dev_audio.z01..z05 + .zip, FSD50K.eval_audio.z01 +
.zip) without merging them and without external tools.

The parts of a split archive are disks 0..n-1 in the order .z01, .z02, ..., .zip. The central directory (in the last
part) records, for every member, the disk where its local header starts and the offset within that disk; the member's
data may continue into the next part. We read the parts as one virtual stream, decompress (stored or deflate) and
check the CRC-32 of every extracted file.

usage: python -I scripts/fsd50k_extract.py <dir with parts | "remote"> <selection json: {clip id: {...}}> <output dir>
With "remote", the parts are read from Zenodo (record 4060432) by HTTP range requests, so only the selected members
(plus each split's central directory) are downloaded.
"""
import json
import os
import struct
import sys
import time
import urllib.request
import zlib
from concurrent.futures import ThreadPoolExecutor

ZENODO = "https://zenodo.org/records/4060432/files/{}?download=1"
UA = {"User-Agent": "research-dataset-extractor/1.0"}


class Parts:
    """The split parts as one read-only stream."""

    def __init__(self, paths):
        self.paths = paths
        self.sizes = [os.path.getsize(p) for p in paths]
        self.starts = [sum(self.sizes[:i]) for i in range(len(paths))]
        self.files = [open(p, "rb") for p in paths]

    def read(self, pos, n):
        out = bytearray()
        while n > 0:
            i = max(j for j, s in enumerate(self.starts) if s <= pos)
            f = self.files[i]
            f.seek(pos - self.starts[i])
            chunk = f.read(min(n, self.sizes[i] - (pos - self.starts[i])))
            if not chunk:
                raise IOError(f"read past end at {pos}")
            out += chunk
            pos += len(chunk)
            n -= len(chunk)
        return bytes(out)


class RemoteParts(Parts):
    """The same stream, read from Zenodo with HTTP range requests (part sizes from the record's API)."""

    def __init__(self, names, sizes):
        self.paths = names
        self.sizes = sizes
        self.starts = [sum(sizes[:i]) for i in range(len(names))]

    def read(self, pos, n):
        out = bytearray()
        while n > 0:
            i = max(j for j, s in enumerate(self.starts) if s <= pos)
            a = pos - self.starts[i]
            m = min(n, self.sizes[i] - a)
            for attempt in range(6):
                try:
                    req = urllib.request.Request(ZENODO.format(self.paths[i]),
                                                 headers={**UA, "Range": f"bytes={a}-{a + m - 1}"})
                    with urllib.request.urlopen(req, timeout=120) as r:
                        assert r.status == 206, r.status
                        chunk = r.read()
                    assert len(chunk) == m, (len(chunk), m)
                    break
                except Exception:  # noqa: BLE001
                    if attempt == 5:
                        raise
                    time.sleep(5 * (attempt + 1))
            out += chunk
            pos += m
            n -= m
        return bytes(out)


def central_directory(parts):
    last = len(parts.paths) - 1
    size = parts.sizes[last]
    tail = parts.read(parts.starts[last] + max(0, size - 70000), min(size, 70000))
    i = tail.rfind(b"PK\x05\x06")
    assert i >= 0, "no end-of-central-directory record"
    (_, disk_no, cd_disk, n_here, n_total, cd_size, cd_off, _) = struct.unpack("<IHHHHIIH", tail[i:i + 22])
    if 0xFFFF in (cd_disk, n_total) or 0xFFFFFFFF in (cd_size, cd_off):
        j = tail.rfind(b"PK\x06\x07", 0, i)                     # zip64 locator
        _, z64_disk, z64_off, _ = struct.unpack("<IIQI", tail[j:j + 20])
        rec = parts.read(parts.starts[z64_disk] + z64_off, 56)
        assert rec[:4] == b"PK\x06\x06", "bad zip64 end record"
        (_, _, _, _, _, cd_disk, _, n_total, cd_size, cd_off) = struct.unpack("<IQHHIIQQQQ", rec)
    cd = parts.read(parts.starts[cd_disk] + cd_off, cd_size)
    entries, p = {}, 0
    for _ in range(n_total):
        assert cd[p:p + 4] == b"PK\x01\x02", "bad central directory entry"
        (method, _, _, crc, csize, usize, nlen, xlen, clen, disk, _, _, off) = struct.unpack(
            "<HHHIIIHHHHHII", cd[p + 10:p + 46])
        name = cd[p + 46:p + 46 + nlen].decode("utf-8", "replace")
        extra = cd[p + 46 + nlen:p + 46 + nlen + xlen]
        q = 0
        while q + 4 <= len(extra):                              # zip64 extra field: values that overflowed
            hid, hlen = struct.unpack("<HH", extra[q:q + 4])
            if hid == 0x0001:
                vals, r = extra[q + 4:q + 4 + hlen], 0
                if usize == 0xFFFFFFFF:
                    usize = struct.unpack("<Q", vals[r:r + 8])[0]; r += 8
                if csize == 0xFFFFFFFF:
                    csize = struct.unpack("<Q", vals[r:r + 8])[0]; r += 8
                if off == 0xFFFFFFFF:
                    off = struct.unpack("<Q", vals[r:r + 8])[0]; r += 8
                if disk == 0xFFFF:
                    disk = struct.unpack("<I", vals[r:r + 4])[0]; r += 4
            q += 4 + hlen
        entries[name] = (method, crc, csize, usize, disk, off)
        p += 46 + nlen + xlen + clen
    return entries


def extract(parts, entry):
    method, crc, csize, usize, disk, off = entry
    pos = parts.starts[disk] + off
    hdr = parts.read(pos, 30)
    assert hdr[:4] == b"PK\x03\x04", "bad local header"
    nlen, xlen = struct.unpack("<HH", hdr[26:30])
    data = parts.read(pos + 30 + nlen + xlen, csize)
    if method == 0:
        out = data
    elif method == 8:
        out = zlib.decompressobj(-15).decompress(data)
    else:
        raise ValueError(f"compression method {method}")
    assert len(out) == usize and (zlib.crc32(out) & 0xFFFFFFFF) == crc, "size or CRC mismatch"
    return out


def main(src, sel_path, out_dir):
    wanted = set(json.load(open(sel_path, encoding="utf-8")))
    os.makedirs(out_dir, exist_ok=True)
    have = {os.path.splitext(f)[0] for f in os.listdir(out_dir) if f.endswith(".wav")}
    sizes = {}
    if src == "remote":
        rec = json.loads(urllib.request.urlopen(urllib.request.Request(
            "https://zenodo.org/api/records/4060432", headers=UA), timeout=60).read().decode("utf-8"))
        sizes = {f["key"]: f["size"] for f in rec["files"]}
    done, failed = 0, []
    for split, n_z in (("dev", 5), ("eval", 1)):
        names = [f"FSD50K.{split}_audio.z{i:02d}" for i in range(1, n_z + 1)] + [f"FSD50K.{split}_audio.zip"]
        parts = (RemoteParts(names, [sizes[n] for n in names]) if src == "remote"
                 else Parts([os.path.join(src, n) for n in names]))
        entries = central_directory(parts)
        todo = [(os.path.splitext(os.path.basename(n))[0], e) for n, e in entries.items()
                if n.endswith(".wav") and os.path.splitext(os.path.basename(n))[0] in wanted - have]

        def one(item):
            clip, entry = item
            try:
                data = extract(parts, entry)
            except Exception as ex:  # noqa: BLE001
                return clip, repr(ex)
            tmp = os.path.join(out_dir, clip + ".wav.part")
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, os.path.join(out_dir, clip + ".wav"))
            return clip, None

        with ThreadPoolExecutor(max_workers=6 if src == "remote" else 1) as ex:
            for k, (clip, err) in enumerate(ex.map(one, todo), 1):
                if err:
                    failed.append((clip, err))
                else:
                    done += 1
                if k % 250 == 0:
                    print(f"{split}: {k}/{len(todo)}", flush=True)
        print(f"{split}: {len(entries)} entries in archive; {len(todo)} wanted here; extracted so far {done}",
              flush=True)
    missing = wanted - {os.path.splitext(f)[0] for f in os.listdir(out_dir) if f.endswith(".wav")}
    print(f"extracted {done}; failed {len(failed)} {failed[:5]}; missing {len(missing)} {sorted(missing)[:10]}")


if __name__ == "__main__":
    main(*sys.argv[1:4])
